def transform(grid):
    g = np.array(grid)
    out = g.copy()
    h, w = g.shape
    bg = background(g)
    def uniform(line):
        return len(set(line.tolist())) == 1 and line[0] != bg
    horizontal = uniform(g[0]) and uniform(g[-1])
    if horizontal:
        c1, c2 = g[0, 0], g[-1, 0]
        span = h - 1
    else:
        c1, c2 = g[0, 0], g[0, -1]
        span = w - 1
    ys, xs = np.where(g == 1)
    pts = list(zip(ys.tolist(), xs.tolist()))
    for which, col in ((0, c1), (1, c2)):
        for y, x in pts:
            p = y if horizontal else x
            d1, d2 = p, span - p
            near = 0 if d1 <= d2 else 1
            if near != which:
                continue
            step = -1 if near == 0 else 1
            if horizontal:
                ny, nx = y + step, x
            else:
                ny, nx = y, x + step
            if 0 <= ny < h and 0 <= nx < w and out[ny, nx] == bg:
                out[ny, nx] = col
        emit(out.copy(), f"Each cell of colour 1 nearer the wall of colour {int(col)} gets a {int(col)} marker on its side facing that wall.")
    return out
